<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Test Results &amp; Reports</h1><p>Class, subject, student, date-range and performance filters.</p></div><button class="btn btn--primary" onclick="window.print()">Print Results</button></header><form class="filter-bar filter-bar--compact"><select class="module-select" id="testResultClass" name="class"><option value="">All Classes</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach ?></select><select class="module-select" name="subject" data-subject-filter="#testResultClass"><option value="">All Subjects</option><?php foreach($subjects as$s):?><option value="<?= $s['id'] ?>" data-class="<?= $s['class_id'] ?>"><?= e($s['name']) ?></option><?php endforeach ?></select><select class="module-select" name="student"><option value="">All Students</option><?php foreach($students as$s):?><option value="<?= $s['id'] ?>"><?= e($s['student_name']) ?></option><?php endforeach ?></select><input class="module-input" type="date" name="from"><input class="module-input" type="date" name="to"><button class="btn btn--secondary">Filter</button></form><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Date</th><th>Test</th><th>Class</th><th>Subject</th><th>Student</th><th>Marks</th><th>Max</th><th>Performance</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?= e($r['test_date']) ?></td><td><?= e($r['title']) ?></td><td><?= e($r['class_name']) ?></td><td><?= e($r['subject_name']) ?></td><td><?= e($r['student_name']) ?></td><td><?= e($r['obtained_marks']) ?></td><td><?= e($r['total_marks']) ?></td><td><?= e($r['percentage']) ?>%</td></tr><?php endforeach ?></tbody></table></div></section></div></div></main>
